<template><OperationsFrame title="菜单管理"><el-form inline v-show="showSearch"><el-form-item label="菜单名称"><el-input v-model="keyword" placeholder="名称或权限标识" clearable/></el-form-item><el-button icon="Search" type="primary" @click="load">搜索</el-button><el-button icon="Refresh" @click="keyword='';load()">重置</el-button></el-form><el-row class="mb8"><el-button type="primary" plain icon="Plus" @click="open()">新增</el-button><el-button plain icon="Sort" @click="expanded=!expanded">展开/折叠</el-button><right-toolbar v-model:showSearch="showSearch" @queryTable="load"/></el-row><el-table :key="String(expanded)+keyword" v-loading="loading" :data="filtered" row-key="menuId" :default-expand-all="expanded||!!keyword" :tree-props="{children:'children'}"><el-table-column prop="menuName" label="菜单名称" min-width="220"/><el-table-column label="类型" width="80"><template #default="{row}">{{{M:'目录',C:'页面',F:'按钮'}[row.menuType]}}</template></el-table-column><el-table-column prop="orderNum" label="排序" width="70"/><el-table-column prop="routePath" label="页面路由" min-width="200" show-overflow-tooltip/><el-table-column prop="perms" label="权限标识" min-width="200" show-overflow-tooltip/><el-table-column label="显示" width="80"><template #default="{row}">{{row.visible==='0'?'显示':'隐藏'}}</template></el-table-column><el-table-column label="状态" width="85"><template #default="{row}"><el-tag :type="row.status==='0'?'success':'info'">{{row.status==='0'?'正常':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button link type="primary" icon="Edit" @click="open(row)">修改</el-button><el-button link type="primary" icon="Plus" :disabled="row.menuType==='F'" @click="open(null,row.menuId)">新增</el-button><el-button link type="primary" icon="Delete" :disabled="!!row.builtin" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
 <el-dialog v-model="visible" :title="form.menuId?'修改菜单':'新增菜单'" width="650px" class="access-dialog" append-to-body :close-on-click-modal="false"><el-form ref="formRef" :model="form" :rules="rules" label-width="110px"><el-form-item label="上级菜单" prop="parentId"><el-tree-select v-model="form.parentId" :data="parentTree" check-strictly :render-after-expand="false" default-expand-all/></el-form-item><el-form-item label="菜单类型" prop="menuType"><el-radio-group v-model="form.menuType" :disabled="!!form.menuId"><el-radio value="M">目录</el-radio><el-radio v-if="form.menuType==='C'" value="C">页面</el-radio><el-radio value="F">按钮</el-radio></el-radio-group></el-form-item><el-form-item label="菜单名称" prop="menuName"><el-input v-model="form.menuName" maxlength="50"/></el-form-item><el-form-item label="显示排序" prop="orderNum"><el-input-number v-model="form.orderNum" :min="0" :max="9999"/></el-form-item><el-form-item v-if="form.menuType==='C'" label="页面路由"><el-input :model-value="form.routePath" disabled/></el-form-item><el-form-item v-if="form.menuType==='F'" label="权限标识" prop="perms"><el-input v-model="form.perms" maxlength="100" placeholder="drilling:资源:操作"/></el-form-item><el-form-item v-else label="菜单图标"><el-input v-model="form.icon" maxlength="100" placeholder="如 tree、user、monitor"/></el-form-item><el-form-item label="显示状态" prop="visible"><el-radio-group v-model="form.visible"><el-radio value="0">显示</el-radio><el-radio value="1">隐藏</el-radio></el-radio-group></el-form-item><el-form-item label="菜单状态" prop="status"><el-radio-group v-model="form.status"><el-radio value="0">正常</el-radio><el-radio value="1">停用</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button type="primary" :loading="saving" @click="save">确 定</el-button><el-button @click="visible=false">取 消</el-button></template></el-dialog>
</OperationsFrame></template>
<script setup>
import {ref,reactive,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import OperationsFrame from '@/views/operations/OperationsFrame.vue'
import {menus,saveMenu,deleteMenu,treeRows} from '@/api/organization'
import usePermissionStore from '@/store/modules/permission'
import useUserStore from '@/store/modules/user'
const expanded=ref(false),rows=ref([]),keyword=ref(''),showSearch=ref(true),loading=ref(false),saving=ref(false),visible=ref(false),form=reactive({}),formRef=ref()
const rules={menuName:[{required:true,message:'请输入菜单名称',trigger:'blur'}],perms:[{required:true,pattern:/^drilling:[A-Za-z0-9_-]+:[A-Za-z0-9_-]+$/,message:'请输入 drilling:资源:操作 格式的权限标识',trigger:'blur'}]}
const filtered=computed(()=>{const keep=nodes=>nodes.flatMap(n=>{const children=keep(n.children);return children.length||!keyword.value||`${n.menuName} ${n.perms}`.includes(keyword.value)?[{...n,children}]:[]});return keep(treeRows(rows.value,'menuId','menuName'))})
const parentTree=computed(()=>[{value:0,label:'主目录',children:convert(treeRows(rows.value.filter(n=>n.menuType!=='F'),'menuId','menuName'))}])
function convert(nodes,blocked=false){return nodes.map(n=>({...n,value:n.menuId,disabled:blocked||n.menuId===form.menuId||(form.menuType!=='F'&&(!n.routePath||n.menuType!=='M')),children:convert(n.children,blocked||n.menuId===form.menuId)}))}
async function load(){loading.value=true;try{rows.value=(await menus()).data}finally{loading.value=false}}
function open(row,parentId=0){Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,{parentId,menuType:parentId?'F':'M',menuName:'',orderNum:0,visible:'0',status:'0',icon:'tree',perms:''},row||{});visible.value=true}
async function refresh(){await useUserStore().getInfo();await usePermissionStore().generateRoutes();await load()}
async function save(){if(!await formRef.value.validate().catch(()=>false))return;saving.value=true;try{await saveMenu(form);visible.value=false;await refresh();ElMessage.success('菜单配置已生效')}catch(e){console.error(e)}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`确认删除“${row.menuName}”？`,'提示',{type:'warning'});await deleteMenu(row.menuId);await refresh();ElMessage.success('菜单已删除')}catch(e){if(e!=='cancel'&&e!=='close')console.error(e)}}
onMounted(load)
</script>
